node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { packContext } from './context-packet.js';
const s = (id, text, priority, required) => ({ id, text, priority, required });
assert.deepEqual(packContext([], Number.MAX_SAFE_INTEGER), { text: '', bytes: 0, included: [], omitted: [] });
for (const budget of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1, NaN, Infinity, '1']) {
  assert.throws(() => packContext([], budget), Error);
}
assert.throws(() => packContext([s('ok', 'x', 0, true), s('bad', 'x', Number.MAX_SAFE_INTEGER + 1, false)], 0), Error);
assert.throws(() => packContext([s('x', 'x', 0, false), s('X', 'x', -1, false)], 0), Error);
const special = s('__proto__\u0000雪', ' a\r\nb ', Number.MAX_SAFE_INTEGER, false);
const frame = `### ${JSON.stringify(special.id)}\n${special.text}\n`;
assert.deepEqual(packContext([special], Buffer.byteLength(frame)), {
  text: frame,
  bytes: Buffer.byteLength(frame),
  included: [special.id],
  omitted: [],
});
console.log('additional API assertions passed');
EOF

